head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[selectbox > P > checkDisabledOnAllCheck]<br/>아이템 리스트창에서 '전체 선택' 아이템 선택 시 비활성화 아이템의 선택 여부를 설정합니다.",
    "validation" : [            
        "아이템이 BindItemSet 으로 정의된 경우에 동작합니다.",
        "allOption=true 이고 enableColumn 속성이 설정되어 비활성화 아이템이 있는 경우 동작합니다.",
        "미설정 시 '전체 선택' 아이템 선택 시 비활성화 아이템도 선택 또는 해제됩니다.",
        "false 설정 시 '전체 선택' 아이템 선택 시 비활성화 아이템은 선택이 제외됩니다.",
        "false 설정 시 '전체 선택' 아이템은 항상 해제 상태로 표시됩니다.",
        "true 설정 시 '전체 선택' 아이템 선택 시 비활성화 아이템도 선택 또는 해제됩니다.",        
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof scwin.target1 !== 'undefined') {
        scwin.target1.remove();
    }    

    // comp 생성
    let grp_comp = document.querySelector('.tc_group_basic');
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    let properties = {
        allOption : true,
        enableColumn : "enable_col",        
        checkDisabledOnAllCheck : con_checkDisabledOnAllCheck.getText(),
    }

    let cList = $c.gcm.createCList(properties);

    strTarget += '<xf:checkcombobox ' + strNameSpace + ' ' + cList + ' style="width:200px; height:30px;">';
    strTarget += '<xf:choices>';
    strTarget += '<xf:itemset nodeset="data:dlt_statusItem">';
    strTarget += '<xf:label ref="label_col"></xf:label>';
    strTarget += '<xf:value ref="value_col"></xf:value>';
    strTarget += '</xf:itemset>';
    strTarget += '</xf:choices>';
    strTarget += '</xf:checkcombobox>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "checkcombobox",
        strTarget,
        grp_comp
    );
}



scwin.btn_getItemInfo_onclick = function (e) {   
    // 해당 class를 가진 모든 input 요소를 선택
    let checkboxElements = document.querySelectorAll('input.w2table_ccb_col_checkbox');

    if (checkboxElements.length == 0)
            wf_body_bottom.getObj("scwin").setReturnValue("checkcombobox 의 아이템 리스트를 한번 오픈해야 아이템 리스트 정보를 가져올 수 있음");

    // 각각의 체크박스 요소의 checked 속성 값을 출력
    for (var i = 0; i < checkboxElements.length; i++) {
        let isChecked = checkboxElements[i].checked; // checked 속성 값 가져오기
        wf_body_bottom.getObj("scwin").setReturnValue("index="+i+" checked : " + isChecked);  
        // wf_body_bottom.getObj("scwin").setReturnValue("index="+i+" index : " + target1.getInfo(i).index);  
        // wf_body_bottom.getObj("scwin").setReturnValue("index="+i+" label : " + target1.getInfo(i).label);  
        // wf_body_bottom.getObj("scwin").setReturnValue("index="+i+" value : " + target1.getInfo(i).value);  
    }
}
